 /// Replaces [role]'s chain (the settings-hub agent-models flow); the new
 /// chain takes effect on the next run. The role is pinned via
 /// [ModelRolesConfig.runtimePinned] so its chain beats every path
 /// override — a runtime switch must never be silently out-voted by the
 /// longest-match entry (gh-243: the Copilot switch that kept running on
 /// Bedrock). A switch of [defaultModelRole] also drops the cached
 /// wrappers of roles that INHERIT the default chain: their wrapper
 /// captured the pre-switch chain and would keep streaming it forever
 /// (gh-243 review). Roles with their own chain keep their wrapper —
 /// cooldown state survives an unrelated switch.
 void setRoleChain(String role, List<ModelRef> chain) {
   if (chain.isEmpty) {
     throw ArgumentError.value(
       chain,
       'chain',
       'a role needs at least one chain entry',
     );
   }
   config = ModelRolesConfig(
     roles: {...config.roles, role: chain},
     pathOverrides: config.pathOverrides,
     retry: config.retry,
     runtimePinned: {...config.runtimePinned, role},
   );
   _wrappers.remove(role);
   if (role == defaultModelRole) {
     // Inherit-default siblings captured the OLD default chain — their
     // cached wrapper would keep streaming the pre-switch chain forever
     // (setRetryPolicy establishes the same rebuild invariant). Roles
     // with their own chain keep their wrapper: only the switched role
     // and the inheritors of the chain it replaced change resolution.
     _wrappers.removeWhere((r, _) => !config.roles.containsKey(r));
   }
 }
